<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getComboboxContext, getComboboxItemContext } from './combobox-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet; keepMounted?: boolean; ref?: HTMLSpanElement | null; } let { children, keepMounted = false, ref = $bindable(null), ...rest }: Props = $props(); const box = getComboboxContext(); const item = getComboboxItemContext(); let selected = $derived(box.isSelected(item.value));</script>{#if keepMounted || selected}<span bind:this={ref} {...rest} hidden={!selected} aria-hidden="true" data-selected={selected ? '' : undefined}>{@render children?.()}</span>{/if}
